-- BÁO HÀNG 1291 — production identity sequence repair after Supabase import.
--
-- The migration imports source primary-key values explicitly into GENERATED BY DEFAULT
-- AS IDENTITY columns. PostgreSQL does not advance an identity sequence when an explicit
-- value is inserted, so each sequence must be aligned with the imported table maximum.
--
-- Safe rule:
--   non-empty table -> set sequence to MAX(id), is_called=true (next value MAX+1)
--   empty table     -> set sequence to 1,       is_called=false (next value 1)

BEGIN;

SELECT setval(pg_get_serial_sequence('public.backup_account_audit','id'),
              greatest(coalesce((SELECT max(id) FROM public.backup_account_audit),0),1),
              coalesce((SELECT max(id) FROM public.backup_account_audit),0) > 0);
SELECT setval(pg_get_serial_sequence('public.catalog_imports','id'),
              greatest(coalesce((SELECT max(id) FROM public.catalog_imports),0),1),
              coalesce((SELECT max(id) FROM public.catalog_imports),0) > 0);
SELECT setval(pg_get_serial_sequence('public.cleanup_audit','id'),
              greatest(coalesce((SELECT max(id) FROM public.cleanup_audit),0),1),
              coalesce((SELECT max(id) FROM public.cleanup_audit),0) > 0);
SELECT setval(pg_get_serial_sequence('public.fallback_token_audit','id'),
              greatest(coalesce((SELECT max(id) FROM public.fallback_token_audit),0),1),
              coalesce((SELECT max(id) FROM public.fallback_token_audit),0) > 0);
SELECT setval(pg_get_serial_sequence('public.inventory_import_errors','id'),
              greatest(coalesce((SELECT max(id) FROM public.inventory_import_errors),0),1),
              coalesce((SELECT max(id) FROM public.inventory_import_errors),0) > 0);
SELECT setval(pg_get_serial_sequence('public.inventory_sync_audit','id'),
              greatest(coalesce((SELECT max(id) FROM public.inventory_sync_audit),0),1),
              coalesce((SELECT max(id) FROM public.inventory_sync_audit),0) > 0);
SELECT setval(pg_get_serial_sequence('public.issue_audit','id'),
              greatest(coalesce((SELECT max(id) FROM public.issue_audit),0),1),
              coalesce((SELECT max(id) FROM public.issue_audit),0) > 0);
SELECT setval(pg_get_serial_sequence('public.realtime_events','id'),
              greatest(coalesce((SELECT max(id) FROM public.realtime_events),0),1),
              coalesce((SELECT max(id) FROM public.realtime_events),0) > 0);
SELECT setval(pg_get_serial_sequence('public.security_audit','id'),
              greatest(coalesce((SELECT max(id) FROM public.security_audit),0),1),
              coalesce((SELECT max(id) FROM public.security_audit),0) > 0);
SELECT setval(pg_get_serial_sequence('public.sheet_export_queue','id'),
              greatest(coalesce((SELECT max(id) FROM public.sheet_export_queue),0),1),
              coalesce((SELECT max(id) FROM public.sheet_export_queue),0) > 0);
SELECT setval(pg_get_serial_sequence('public.staff_sync_audit','id'),
              greatest(coalesce((SELECT max(id) FROM public.staff_sync_audit),0),1),
              coalesce((SELECT max(id) FROM public.staff_sync_audit),0) > 0);

COMMIT;
